export type FormulaSection = { h: string; items: [string, string][] }
export type CheckSpec = [string, number]
export type AssignPart = { p: string; steps: string[]; checks?: CheckSpec[]; write?: string }
export type AssignQ = { n: string; t: string; ch: string; tests: string; parts: AssignPart[] }
export type PracticeQ = { id: string; topic?: string; stem: string; opts: string[]; a: number; hint: string; sol: string[] }
export type PdfRef = { file: string; title: string; desc: string; primary?: boolean }
export type CourseContent = {
  focus: string
  formulas: FormulaSection[]
  formulasLabel?: string
  quizLabel?: string
  quizNote?: string
  sourceNote?: string
  pdfs?: PdfRef[]
  drills?: string[]
  calcTip?: string
  assignment?: { title: string; due: string; qs: AssignQ[] }
  practice?: PracticeQ[]
}

